files.content:
.ds-link-list {
  display: flex;
  flex-direction: column;
  gap: var(--gap-500);
}

.ds-link-list__item {
  display: flex;
  align-items: flex-start;
  gap: var(--gap-400);
  text-decoration: none;
  color: inherit;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-link-list__item:hover {
  opacity: 0.8;
}

.ds-link-list__icon-wrap {
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ds-link-list__logo {
  width: 28px;
  height: 28px;
  object-fit: contain;
}

.ds-link-list__symbol {
  font-size: 28px;
  line-height: 1;
  color: var(--color-text-secondary);
}

.ds-link-list__content {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.ds-link-list__title {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  color: var(--color-text-primary);
}

.ds-link-list__open-icon {
  --icon-size: var(--icon-size-500);
  color: var(--color-text-tertiary);
}

.ds-link-list__sub {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
}

import type React from 'react';
import './LinkList.css';
import '../../fonts/material-symbols.css';

export interface LinkListItem {
  /** Link destination */
  href: string;
  /** Primary label — shown with the open_in_new icon */
  label: string;
  /** One or more subtitle lines shown below the label */
  sub?: string | string[];
  /** Path to a logo image (preferred over icon when both are set) */
  logo?: string;
  /** Alt text for the logo — defaults to empty string (decorative) */
  logoAlt?: string;
  /** Icon used when no logo is provided — Material Symbol name (string, e.g. "emoji_events") or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Open in a new tab. Defaults to true; set false for links inside the same site, which swaps the open_in_new indicator for arrow_forward. */
  newTab?: boolean;
}

export interface LinkListProps {
  /** Links to render, in display order */
  items: LinkListItem[];
  /** Additional CSS classes */
  className?: string;
}

export const LinkList = ({ items, className = '' }: LinkListProps) => {
  const classes = ['ds-link-list', className].filter(Boolean).join(' ');
  return (
    <div className={classes}>
      {items.map((item) => {
        const subs = item.sub
          ? Array.isArray(item.sub)
            ? item.sub
            : [item.sub]
          : [];

        const newTab = item.newTab ?? true;

        return (
          <a
            key={item.href + item.label}
            href={item.href}
            target={newTab ? '_blank' : undefined}
            rel={newTab ? 'noopener noreferrer' : undefined}
            className="ds-link-list__item"
          >
            <span className="ds-link-list__icon-wrap" aria-hidden="true">
              {item.logo ? (
                <img
                  src={item.logo}
                  alt={item.logoAlt ?? ''}
                  className="ds-link-list__logo"
                  width={28}
                  height={28}
                />
              ) : typeof item.icon === 'string' || item.icon == null ? (
                <span className="material-symbols-rounded ds-link-list__symbol">
                  {item.icon ?? 'link'}
                </span>
              ) : (
                <span className="ds-link-list__symbol">{item.icon}</span>
              )}
            </span>

            <div className="ds-link-list__content">
              <div className="ds-link-list__title">
                <span>{item.label}</span>
                <span className="material-symbols-rounded ds-link-list__open-icon" aria-hidden="true">
                  {newTab ? 'open_in_new' : 'arrow_forward'}
                </span>
              </div>
              {subs.map((s, i) => (
                <span key={i} className="ds-link-list__sub">{s}</span>
              ))}
            </div>
          </a>
        );
      })}
    </div>
  );
};
